import {
    Table,
    DateTimeColumn,
    DurationColumn,
    IntegerColumn,
    BooleanColumn,
    GenericColumn,
    StringColumn,
    ReferenceColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const task_sla = Table({
    actions: ['read', 'update', 'create'],
    allowClientScripts: true,
    allowNewFields: true,
    allowUiActions: true,
    allowWebServiceAccess: true,
    attributes: {
        kagami_csindex_enabled: true,
    },
    display: 'sla',
    label: 'Task SLA',
    name: 'task_sla',
    schema: {
        end_time: DateTimeColumn({
            label: 'Stop time',
        }),
        business_time_left: DurationColumn({
            label: 'Business time left',
            maxLength: 40,
        }),
        sys_mod_count: IntegerColumn({
            label: [
                {
                    label: 'Updates',
                    plural: 'Updates',
                    language: 'en',
                },
            ],
        }),
        original_breach_time: DateTimeColumn({
            label: [
                {
                    hint: 'Original time the SLA will breach. Set when the SLA is attached.',
                    label: 'Original breach time',
                    plural: 'Original breach times',
                    language: 'en',
                },
            ],
        }),
        pause_duration: DurationColumn({
            label: [
                {
                    hint: 'Total time spent in a pause state',
                    label: 'Pause duration',
                    plural: 'Pause durations',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        percentage: GenericColumn({
            attributes: {
                target_threshold_colors: '0:#71e279;50:#fcc742;75:#fc8a3d;100:#f95050',
            },
            columnType: 'percent_complete',
            label: 'Actual elapsed percentage',
            maxLength: 15,
        }),
        stage: StringColumn({
            default: 'in_progress',
            dropdown: 'dropdown_with_none',
            label: 'Stage',
        }),
        sys_updated_by: StringColumn({
            label: [
                {
                    label: 'Updated by',
                    plural: 'Updated by',
                    language: 'en',
                },
            ],
        }),
        sla: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: [
                {
                    label: 'SLA definition',
                    plural: 'SLA Definitions',
                    language: 'en',
                },
            ],
            referenceTable: 'contract_sla',
        }),
        business_duration: DurationColumn({
            label: [
                {
                    label: 'Business elapsed time',
                    plural: 'Business elapsed times',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=CSHelp:Actual-And-Business-Elapsed-Times',
                },
            ],
            maxLength: 40,
        }),
        timezone: StringColumn({
            dropdown: 'dropdown_with_none',
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'sys_user',
                field: 'time_zone',
            },
            label: [
                {
                    label: 'Timezone',
                    plural: 'Timezones',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=CSHelp:Time-Zones-In-SLAs',
                },
            ],
        }),
        sys_created_by: StringColumn({
            label: [
                {
                    label: 'Created by',
                    plural: 'Created by',
                    language: 'en',
                },
            ],
        }),
        task: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            cascadeRule: 'delete',
            label: 'Task',
            referenceTable: 'task',
        }),
        time_left: DurationColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `if (!current.planned_end_time.nil()) {
   if (current.active == true && current.stage != 'paused') {
      var durSeconds = gs.dateDiff(gs.nowDateTime(), current.planned_end_time.getDisplayValue(), true);
      if (durSeconds > 0) {
         answer = gs.dateDiff(gs.nowDateTime(), current.planned_end_time.getDisplayValue(), false);
      } else {
         answer = '00 00:00:00';
      }
   } else {
      current.time_left;
   }
} else {
   var newDur2 = new GlideDuration(0);
   answer = newDur2.getDurationValue();
}`,
            },
            label: 'Actual time left',
            maxLength: 40,
        }),
        schedule: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    label: 'Schedule',
                    plural: 'Schedules',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=CSHelp:Schedules-Within-SLA',
                },
            ],
            referenceTable: 'cmn_schedule',
        }),
        sys_updated_on: DateTimeColumn({
            label: [
                {
                    label: 'Updated',
                    plural: 'Updated',
                    language: 'en',
                },
            ],
        }),
        start_time: DateTimeColumn({
            default: 'javascript:gs.nowDateTime()',
            label: 'Start time',
        }),
        business_percentage: GenericColumn({
            attributes: {
                target_threshold_colors: '0:#71e279;50:#fcc742;75:#fc8a3d;100:#f95050',
            },
            columnType: 'percent_complete',
            label: 'Business elapsed percentage',
            maxLength: 15,
        }),
        has_breached: BooleanColumn({
            label: 'Has breached',
        }),
        sys_created_on: DateTimeColumn({
            label: [
                {
                    label: 'Created',
                    plural: 'Created',
                    language: 'en',
                },
            ],
        }),
        planned_end_time: DateTimeColumn({
            label: [
                {
                    hint: 'Time the SLA will breach. Adjusted for pause duration.',
                    label: 'Breach time',
                    plural: 'Breach times',
                    language: 'en',
                },
            ],
        }),
        pause_time: DateTimeColumn({
            label: 'Pause time',
        }),
        duration: DurationColumn({
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `if (!current.start_time.nil()) {
   if (current.active == true && current.stage != 'paused') {
      var totalElapsedMS = gs.dateDiff(current.start_time.getDisplayValue(), gs.nowDateTime(), true) * 1000;
      var pausedMS = 0;
      if (current.pause_duration) {
         pausedMS = current.pause_duration.getGlideObject().getNumericValue();
      }
      var adjustedMS = totalElapsedMS - pausedMS;
      var newDur = new GlideDuration(adjustedMS);
      answer = newDur.getDurationValue();
   } else {
      current.duration;
   }
} else {
   var newDur2 = new GlideDuration(0);
   answer = newDur2.getDurationValue();
}`,
            },
            label: [
                {
                    label: 'Actual elapsed time',
                    plural: 'Actual elapsed times',
                    language: 'en',
                    url: 'http://docs.servicenow.com/?context=CSHelp:Actual-And-Business-Elapsed-Times',
                },
            ],
            maxLength: 40,
        }),
        business_pause_duration: DurationColumn({
            label: [
                {
                    hint: 'Business time spent in a pause state',
                    label: 'Business pause duration',
                    plural: 'Business pause durations',
                    language: 'en',
                },
            ],
            maxLength: 40,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
